          const path = require('node:path');
          const engine = require(path.join(process.env.CLOUSEAU_ROOT, 'src/central-version.cjs')).environmentEngine();
          if (engine) {
            fs.mkdirSync('work', {recursive: true});
            fs.writeFileSync('work/clouseau-engine.json', JSON.stringify(engine, null, 2) + '\n');
            await core.summary.addRaw(`Clouseau frozen commit: ${engine.sha}\n\nEngine digest: ${engine.digest}\n`).write();
          }
