  }
  fs.writeFileSync(path.join(root, 'service.py'), SOURCE + 'message = "# pragma: no cover"\nother = \'\\\' # pragma: no cover\'\n' +
    'long = """\n# pragma: no cover\n"""\nraw = r"\\\\"\nbytes_ = b"x"\nformatted = f"{1}"\n# an ordinary comment\n');
