function istanbul(run, files = {}) {
  return temp(directory => {
    const root = path.join(directory, 'src');
    write(root, {'service.ts': 'export function f(ok: boolean) {\n  return ok ? 1 : 0;\n}\n', ...files});
    const name = path.join(root, 'service.ts');
